// TH14 synthetic bullet aliases (target TH18 row bases), copied from transcribe/th14/touhou-bullets.ecl
// Source type 18 -> target 18 (BIG_BALL); source type 5 -> target 5 (BALL2).
const TH14_BIG_BALL: int = 640;
const TH14_BALL2: int = 432;

// TH14 v1.00b Stage 3 Boss nonspell 2 (st03bs.ecl.txt::Boss2, source lines 124-178).
// Source timerReset :131 starts the 2700-frame interrupt clock; the attack loop starts
// after the 140-frame entry wait (:156). setInterrupt(2100,2700,"BossCard2") is the exit
// evidence only - the next card is not transcribed here. No DPS shell: HP path is inert.
const TIME_LIMIT: int = 3184;   // 120 opening + 2700 source timer + 360 tail + 4 launch margin
const OPENING_BUFFER: int = 120;
const SOURCE_TIMER: int = 2700;

// Per-wave parameters consumed by the bullet task (one async task per main bullet).
const G_SPIN: int = 16;
const G_COLOR: int = 17;
const G_WAYS: int = 18;

// Source %F0 = 0.034907 rad/frame (2 deg/frame) and SHOOT second angle = 0.034906585 rad.
const TWO_DEG: int = 364;

// ---------------------------------------------------------------------------
// Main bullet task: Boss2_at main bullets (st03bs.ecl.txt:180-220)
//   etSprite(0,18,1)             -> TH14_BIG_BALL color 1
//   etEx ANIM/BRIGHT/SPEEDUP     -> presentation, omitted
//   etEx WAIT(10)                -> the first 10 frames hold the EX cursor
//   etEx ANGLE_ACCEL(50, r=.035, s=%F0)
//                                -> 50 ticks of speed += 0.035 and angle += F0
//   etEx SHOOT(3, idx10, ways, 3, r=-999, s=2deg, m=-999, n=2.5)
//                                -> after age 60 fire a fixed ring of `ways` ways x 3
//                                   layers around the parent's current angle; layer
//                                   speeds run parent speed -> 2.5; r/m keep parent
//                                   angle/speed (negative sentinels, TH14 values).
//   SHOOT_DATA sprite 5 / color $A -> TH14_BALL2 with per-wave color 6/2/4
//   child EX index 10-12 (ANIM/sound/BRIGHT) -> presentation, omitted
// ---------------------------------------------------------------------------
async sub b2_split() {
    var spin: int = global(G_SPIN);
    var color: int = global(G_COLOR);
    var ways: int = global(G_WAYS);
    wait(9);                       // task starts 1 frame after spawn -> age 10
    set_ang_vel(0, spin);
    set_accel(0, 0.035fx);
    wait(50);                      // 50 polar ticks, same as ANGLE_ACCEL a=50
    stop_fx(0);
    var spd: fx = $self_speed;     // layer 0 = parent speed (SHOOT m=-999)
    var base: angle = $self_angle; // ring axis = parent angle (SHOOT r=-999)
    var dstep: fx = (2.5fx - spd) / 2fx;   // (n - s0) / (layers - 1)
    for q in 0..3 {                // native order: layer outer, way inner
        var s: fx = spd + dstep * (q as fx);
        var layer: angle = (q * TWO_DEG) as angle;
        for i in 0..ways {
            var off: int = (i * 65536) / ways;
            var a: angle = base + (off as angle) + layer;
            _ = fire(TH14_BALL2, color, $self_x, $self_y, s, a, none, none);
        }
    }
}

// One source Boss2_at wave: etNew/etAim(3)/etSprite/etCount/etAngle/etSpeed/etDist/etOn.
// etCount main = 13 on Easy, 24 otherwise; SHOOT ways = 2/2/3/4 by rank.
// etDist 16 minus ANIM birth retreat 4*1.4 leaves 10.4 px net along each angle.
sub b2_fire_wave(count: int, color: int, ways: int, spin: int) {
    set_global(G_SPIN, spin);
    set_global(G_COLOR, color);
    set_global(G_WAYS, ways);
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 1);
    sh_ring(0, 1);                 // etAim(0,3): full ring at a random base angle
    sh_aim(0, 0);
    sh_count(0, count, 1);
    sh_speed(0, 1.4fx, 0fx);       // etSpeed(1.4, 1.0), one layer -> 1.4
    sh_angle(0, rand(65536) as angle, 0deg);   // etAngle(%RANDRAD, ...), one draw per wave
    sh_dist(0, 10.4fx);
    sh_task(0, b2_split);
    sh_fire(0);
}

// ---------------------------------------------------------------------------
// moveRand(60,4,0.4) + moveLimit(0,128,280,96) recipe (th16/movement.md sample).
// Limit rectangle x in [-140,140], y in [80,176]; direction inner zone x +/-70,
// y 104..152. Speed is linear 0.4*(1-k/60) regardless of the mode-4 parameter.
// Boss START (0,128) is the shared-entry reachable representative.
// ---------------------------------------------------------------------------
sub b2_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        var frac: fx = (60 - k) as fx / 60;
        speed = frac * 0.4fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub b2_begin_move(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    b2_arm_next_step();
}

sub b2_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +/- pi/2 guard, epsilon 0.05 rad ~ 522 BAM
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    b2_begin_move(a as angle);
}

// ---------------------------------------------------------------------------
// Boss2 entry (lines 124-178): shared-entry box 48x48 -> radius 24, invuln shell,
// movePosTime(60,4,0,128), moveVel(0,0), wait(140), moveLimit, I0/F0.
// Loop: wave colors 6/2/4, F0 flips once after the first wave of each cycle.
// 12 cycles -> last wave at local 2680; native timeout at 2700 -> stop firing and
// run the source timeout clear (etClear(640), no star conversion). Tail bullets of the
// last wave are removed by that clear; remaining window is the training tail.
// ---------------------------------------------------------------------------
async sub b2_attack() {
    set_invuln(65535);
    set_hitbox(24fx);              // setHitbox(48,48), circle branch first value * 0.5
    set_hurtbox(24fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);   // movePosTime(60,4,0,128)
    move_vel(0, 0deg, 0fx, EASE_LINEAR);      // moveVel/moveVelTime zero write
    wait(140);
    var rank: int = global(GVAR_RANK);
    var count: int = 24;           // !N/!H/!LO main count
    if rank == 0 { count = 13; }   // !E
    var ways: int = 2;             // !E / !N SHOOT ways
    if rank == 2 { ways = 3; }     // !H
    if rank >= 3 { ways = 4; }     // !LO
    var spin: int = TWO_DEG;       // %F0 = +0.034907 rad/frame
    for cycle in 0..12 {
        wait(60);
        b2_fire_wave(count, 6, ways, spin);
        wait(30);
        spin = -spin;              // %F0 = %F0 * -1 after wave 1
        b2_fire_wave(count, 2, ways, spin);
        wait(30);
        b2_fire_wave(count, 4, ways, spin);
        if cycle < 11 {
            wait(30);
            b2_move_rand();
            for i in 0..60 { wait(1); b2_arm_next_step(); }
            wait(10);
        }
    }
    wait(20);                      // local 2680 -> 2700 (native timeout)
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    loop { wait(1); }
}

// ---------------------------------------------------------------------------
// Independent invulnerable shell (TH14 validation.md / TH18 appendix).
// ---------------------------------------------------------------------------
async sub b2_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 12100, 0, 0, 0, b2_attack);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, b2_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
